// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRussoOne = makeLoadFont('RussoOne');
const loadTeko = makeLoadFont('Teko');

// Load military and tactical sci-fi Google Fonts at module level
const { fontFamily: russoFamily } = loadRussoOne();
const { fontFamily: tekoFamily } = loadTeko();



export type TacticalTimerProps = Record<string, any>;

const TacticalTimer: React.FC<TacticalTimerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 60,
  primaryColor = "#e50000",
  glowIntensity = 1.0,
  startMinutes = 1,
  startSeconds = 0,
  endMinutes = 0,
  endSeconds = 0,
  subtext = "TO LIVE FIRE",
  glitchEnabled = true,
  pulseOnTick = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color parse safety
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const virtualStart = startMinutes * 60 + startSeconds;
  const virtualEnd = endMinutes * 60 + endSeconds;

  // Real-time decreasing virtual seconds remaining: counts down exactly 1 second per video second
  const elapsedSeconds = frame / fps;
  const currentVirtualSecondsFloat = Math.max(virtualEnd, virtualStart - elapsedSeconds);
  const currentVirtualSeconds = Math.ceil(currentVirtualSecondsFloat);

  // Maintain progress logic for dependent elements (like warning glitch triggers near end of countdown)
  const totalVirtualDuration = Math.max(0, virtualStart - virtualEnd);
  const progress = totalVirtualDuration > 0 
    ? Math.min(1, elapsedSeconds / totalVirtualDuration)
    : 1;

  // Generate a beautiful heartbeat visual pulse that peaks exactly on the physical seconds changes
  const secondsFraction = (frame % fps) / fps;
  const tickPulse = pulseOnTick
    ? Math.exp(-10 * secondsFraction) // sharp rise exactly on the tick, then fast decay
    : 0;

  // Alert glitching active near the end of the countdown
  const isAlertGlitching = glitchEnabled && progress > 0.9 && random(frame) > 0.85;
  const isGlitching = isAlertGlitching;

  // Helper to generate deterministic glitched time text
  const getGlitchedTimeText = (seedFrame: number) => {
    const chars = "0123456789:";
    let res = "";
    for (let i = 0; i < 5; i++) {
      if (i === 2) {
        res += ":";
      } else {
        const charIdx = Math.floor(random(`glitch-${seedFrame}-${i}`) * 10);
        res += chars[charIdx];
      }
    }
    return res;
  };

  const displayMinutes = Math.floor(currentVirtualSeconds / 60);
  const displaySeconds = currentVirtualSeconds % 60;
  const formattedMinutes = String(displayMinutes).padStart(2, "0");
  const formattedSeconds = String(displaySeconds).padStart(2, "0");
  const realTimeText = `${formattedMinutes}:${formattedSeconds}`;
  
  const finalTimeText = isGlitching ? getGlitchedTimeText(frame) : realTimeText;

  // Instant display without entrance transitions
  const frameScale = 1;
  const frameOpacity = 1;
  const textSlideUp = 0;
  const textOpacity = 1;
  const textTracking = 4;

  // Glowing style helpers
  const primaryGlow = `${primaryColor}${Math.round(75 * glowIntensity).toString(16).padStart(2, "0")}`;
  const pulseGlow = `${primaryColor}${Math.round(150 * tickPulse * glowIntensity).toString(16).padStart(2, "0")}`;

  // Layout percentages (responsive rectangle scaling)
  const borderWidth = width * 0.85;
  const borderHeight = height * 0.75;
  const timerBoxWidth = borderWidth * 0.9;
  const timerBoxHeight = borderHeight * 0.55;
  const borderThickness = Math.max(6, Math.min(width, height) * 0.013);

  // Outer border framing details - aligned as a rectangle centered on screen
  const outerBorderStyle: React.CSSProperties = {
    position: "absolute",
    width: borderWidth,
    height: borderHeight,
    top: (height - borderHeight) / 2,
    left: (width - borderWidth) / 2,
    border: `${borderThickness}px solid ${primaryColor}`,
    borderRadius: 0,
    pointerEvents: "none",
    boxShadow: `0px 0px ${40 * glowIntensity}px ${primaryGlow}, inset 0px 0px ${30 * glowIntensity}px ${primaryGlow}`,
    zIndex: 5,
    transition: "none",
  };

  // Styling maps
  const outerContainerStyle: React.CSSProperties = {
    position: "absolute",
    top: (height - borderHeight) / 2,
    left: (width - borderWidth) / 2,
    width: borderWidth,
    height: borderHeight,
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    padding: `${borderHeight * 0.05}px`,
    boxSizing: "border-box",
    transition: "none",
  };

  const timerBoxStyle: React.CSSProperties = {
    position: "relative",
    width: timerBoxWidth,
    height: timerBoxHeight,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "transparent",
    opacity: frameOpacity,
    transform: `scale(${frameScale})`,
    transition: "none",
  };

  // Decorative diagonal slashes embedded in the borders
  const renderTopSlashes = () => {
    return (
      <div
        style={{
          position: "absolute",
          top: 0,
          left: "50%",
          transform: "translateX(-50%)",
          backgroundColor: finalBgColor,
          paddingLeft: "15px",
          paddingRight: "15px",
          height: borderThickness + 12,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: "8px",
          transition: "none",
        }}
      >
        {[...Array(4)].map((_, i) => (
          <div
            key={`top-slash-${i}`}
            style={{
              width: "8px",
              height: borderThickness * 1.5,
              backgroundColor: primaryColor,
              transform: "skewX(-30deg)",
              boxShadow: `0px 0px 8px ${primaryColor}`,
              transition: "none",
            }}
          />
        ))}
      </div>
    );
  };

  const renderBottomSlashes = () => {
    return (
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: "50%",
          transform: "translateX(-50%)",
          backgroundColor: finalBgColor,
          paddingLeft: "15px",
          paddingRight: "15px",
          height: borderThickness + 12,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: "8px",
          transition: "none",
        }}
      >
        {[...Array(4)].map((_, i) => (
          <div
            key={`bottom-slash-${i}`}
            style={{
              width: "8px",
              height: borderThickness * 1.5,
              backgroundColor: primaryColor,
              transform: "skewX(-30deg)",
              boxShadow: `0px 0px 8px ${primaryColor}`,
              transition: "none",
            }}
          />
        ))}
      </div>
    );
  };

  const renderSideSlashes = (side: "left" | "right") => {
    return (
      <div
        style={{
          position: "absolute",
          [side]: 0,
          top: "50%",
          transform: "translateY(-50%)",
          backgroundColor: finalBgColor,
          paddingTop: "15px",
          paddingBottom: "15px",
          width: borderThickness + 12,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "8px",
          transition: "none",
        }}
      >
        {[...Array(3)].map((_, i) => (
          <div
            key={`${side}-slash-${i}`}
            style={{
              width: borderThickness * 1.5,
              height: "8px",
              backgroundColor: primaryColor,
              transform: "skewY(-30deg)",
              boxShadow: `0px 0px 8px ${primaryColor}`,
              transition: "none",
            }}
          />
        ))}
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, transition: "none" }}>
      {/* Subtle Tactical Shutter Overlay */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "repeating-linear-gradient(0deg, rgba(0,0,0,0.2) 0px, rgba(0,0,0,0.2) 2px, transparent 2px, transparent 4px)",
          pointerEvents: "none",
          zIndex: 10,
          transition: "none",
        }}
      />

      {/* Heartbeat pulse glow overlay */}
      {pulseOnTick && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: `radial-gradient(circle, ${pulseGlow} 0%, transparent 70%)`,
            pointerEvents: "none",
            zIndex: 1,
            transition: "none",
          }}
        />
      )}

      {/* Outer Border Frame (Rectangle) */}
      <div style={outerBorderStyle}>
        {renderTopSlashes()}
        {renderBottomSlashes()}
        {renderSideSlashes("left")}
        {renderSideSlashes("right")}
      </div>

      <div style={outerContainerStyle}>
        {/* Main Timer Display Box */}
        <div style={timerBoxStyle}>
          <span
            style={{
              fontFamily: russoFamily,
              fontSize: borderHeight * 0.45,
              color: primaryColor,
              letterSpacing: "4px",
              textAlign: "center",
              lineHeight: 1,
              textShadow: `0px 0px ${35 * glowIntensity}px ${primaryColor}, 0px 0px ${70 * glowIntensity}px ${primaryColor}`,
              userSelect: "none",
              transform: isGlitching ? `skewX(${random(frame) * 10 - 5}deg)` : "none",
              transition: "none",
            }}
          >
            {finalTimeText}
          </span>
        </div>

        {/* Tactical Separator Line */}
        <div
          style={{
            width: borderWidth * 0.8,
            height: "4px",
            background: `linear-gradient(90deg, transparent 5%, ${primaryColor} 50%, transparent 95%)`,
            boxShadow: `0px 0px 15px ${primaryColor}`,
            marginTop: borderHeight * 0.06,
            marginBottom: borderHeight * 0.02,
            opacity: textOpacity,
            transition: "none",
          }}
        />

        {/* Explanatory/Action Subtext */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textSlideUp}px)`,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: tekoFamily,
              fontSize: borderHeight * 0.15,
              fontWeight: 800,
              color: primaryColor,
              textTransform: "uppercase",
              letterSpacing: `${textTracking}px`,
              textShadow: `0px 0px ${20 * glowIntensity}px ${primaryColor}`,
              lineHeight: 1,
              transition: "none",
            }}
          >
            {subtext}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TacticalTimer;